import '@kerfjs/ui/layout.css';
import { EmptyState } from '@kerfjs/ui/empty-state';
import { LoadingSpinner } from '@kerfjs/ui/loading-spinner';
import { PageHeader } from '@kerfjs/ui/page-header';
import { StateBanner } from '@kerfjs/ui/state-banner';
import { delegate } from './events';
import './workspace.css';

type Item = { id: string; title: string; summary: string };
export function createList(root: HTMLElement, paint: (html: ReturnType<typeof PageHeader>) => void, fetchItems: (signal: AbortSignal) => Promise<Item[]>, createItem: () => void) {
  let items: Item[] = [];
  let loaded = false;
  let loading = false;
  let error = '';
  let request: AbortController | undefined;
  let disposed = false;
  const render = () => <section class="list-workspace app-root kui-layout" aria-label="Tasks">
    <PageHeader title="Tasks" action={<button class="app-button" type="button" data-action="tasks-refresh" disabled={loading}>Refresh</button>} />
    <div class="kui-scroll-owner kui-pane-body kui-section-stack">
      {error && <StateBanner tone="danger" urgency="alert" title="Tasks could not be loaded" detail={loaded ? 'Saved results remain available. Retry to get the latest tasks.' : 'Check your connection and retry.'} action={<button class="app-button" type="button" data-action="tasks-retry">Retry</button>} />}
      {loading && !loaded && <EmptyState title="Loading tasks" detail="Your workspace is being loaded." busy />}
      {loading && loaded && <StateBanner title="Refreshing tasks" detail="Showing saved results while the latest tasks load." tone="info" action={<LoadingSpinner label="Refreshing tasks" />} />}
      {loaded && !items.length && <EmptyState title="No tasks yet" detail="Create a task to start this workspace." action={<button type="button" class="app-button" data-action="tasks-create">Create task</button>} />}
      {!!items.length && <ul aria-label="Tasks">{items.map(item => <li key={item.id}><strong>{item.title}</strong><p>{item.summary}</p></li>)}</ul>}
    </div>
  </section>;
  async function refresh() {
    request?.abort();
    const current = new AbortController();
    request = current;
    loading = true;
    error = '';
    paint(render());
    try {
      const next = await fetchItems(current.signal);
      if (disposed || current !== request) return;
      items = next; loaded = true;
    } catch (failure) {
      if (disposed || current !== request || current.signal.aborted) return;
      error = 'Unable to load tasks';
    } finally {
      if (!disposed && current === request) { loading = false; paint(render()); }
    }
  }
  const off = delegate(root, 'click', '[data-action]', element => {
    if (element.dataset.action === 'tasks-create') createItem();
    if (['tasks-retry', 'tasks-refresh'].includes(element.dataset.action!)) void refresh();
  });
  void refresh();
  return { render, refresh, dispose() { disposed = true; request?.abort(); off(); } };
}

